export const KIND = {"id":73,"example":{"id":"E73","kind":73,"source":"aether","statement":["Write a function `spaced::write(int number)` that returns the number in digits as a `std::string`, with a space before each group of 3 digits counted from the right.","1234567 gives `1 234 567`, 1000 gives `1 000` and 999 gives `999`.","Limits: 0 ≤ number ≤ 2 000 000 000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <string>","","namespace spaced {","","std::string padded(int group)","{","    if (group < 10) {","        return \"00\" + std::to_string(group);","    } else if (group < 100) {","        return \"0\" + std::to_string(group);","    } else {","        return std::to_string(group);","    }","}","","std::string last_group(int number)","{","    if (number < 1000) {","        return std::to_string(number);","    } else {","        return padded(number % 1000);","    }","}","","std::string write(int number)","{","    std::string result {last_group(number)};","    while (number >= 1000) {","        number /= 1000;","        result = last_group(number) + \" \" + result;","    }","    return result;","}","","}  // namespace spaced"],"frame":[0,2,4,36],"labels":[{"at":6,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":8,"level":2,"text":"Give back the group with 2 zeros in front below 10, 1 zero below 100, else as it is."},{"at":17,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":19,"level":2,"text":"Give back the whole number below 1000, else its last 3 digits padded."},{"at":26,"level":1,"text":"Write a function that repeats a step until a condition holds and gives back the result."},{"at":28,"level":2,"text":"Start the result with the last group."},{"at":29,"level":2,"text":"While groups are left, drop the last group, then put the new last group and a space at the front."},{"at":33,"level":2,"text":"Give back the result."}],"blanks":[]}},"trace":{"id":"T73","lines":["#include <iostream>","#include <print>","#include <string>","std::string grouped(int number) noexcept","{","    std::string result {std::to_string(number % 100)};","    while (number >= 100) {","        number /= 100;","        result = std::to_string(number % 100) + \" \" + result;","    }","    return result;","}","int main()","{","    int number {0};","    std::cin >> number;","    std::println(\"{}\", grouped(number));","}"],"columns":["number","result"],"inputs":["12345\n","7050\n"],"rows":[{"line":15,"values":["0",""]},{"line":16,"values":["12345",""]},{"line":6,"values":["12345","45"]},{"line":7,"values":["12345","45"]},{"line":8,"values":["123","45"]},{"line":9,"values":["123","23 45"]},{"line":7,"values":["123","23 45"]},{"line":8,"values":["1","23 45"]},{"line":9,"values":["1","1 23 45"]},{"line":7,"values":["1","1 23 45"]},{"line":17,"values":["12345",""]}],"output":"70 50\n"},"traces":[],"problems":{"73.01":{"id":"73.01","kind":73,"source":"exercism","statement":["Write a function `say::in_english(unsigned long long number)` that returns the number in English words.","Write the words in lower case, separated by single spaces, with a dash inside the numbers from 21 to 99 that are not a multiple of 10 (`twenty-two`).","Write no `and`, and leave out every part that is zero: 1002345 is `one million two thousand three hundred forty-five`.","0 gives `zero`.","Throw `std::domain_error` for a number above 999 999 999 999 (a negative number passed in becomes such a number).","Limits: 0 ≤ number ≤ 999 999 999 999 for a number in words."],"examples":[{"input":"zero","output":""}],"tests":[{"input":"one","output":""},{"input":"fourteen","output":""},{"input":"twenty","output":""},{"input":"twenty-two","output":""},{"input":"thirty","output":""},{"input":"ninety-nine","output":""},{"input":"one hundred","output":""},{"input":"one hundred twenty-three","output":""},{"input":"two hundred","output":""},{"input":"nine hundred ninety-nine","output":""},{"input":"one thousand","output":""},{"input":"one thousand two hundred thirty-four","output":""},{"input":"one million","output":""},{"input":"one million two thousand three hundred forty-five","output":""},{"input":"one billion","output":""},{"input":"a big number","output":""},{"input":"numbers below zero are out of range","output":""},{"input":"numbers above 999,999,999,999 are out of range","output":""}],"solution":{"lines":["#pragma once","","#include <stdexcept>","#include <string>","#include <vector>","","namespace say {","","std::string below_hundred(unsigned long long number)","{","    const std::vector<std::string> ones {","        \"zero\", \"one\", \"two\", \"three\", \"four\", \"five\", \"six\",","        \"seven\", \"eight\", \"nine\", \"ten\", \"eleven\", \"twelve\",","        \"thirteen\", \"fourteen\", \"fifteen\", \"sixteen\",","        \"seventeen\", \"eighteen\", \"nineteen\"};","    const std::vector<std::string> tens {","        \"\", \"\", \"twenty\", \"thirty\", \"forty\", \"fifty\", \"sixty\",","        \"seventy\", \"eighty\", \"ninety\"};","    if (number < 20) {","        return ones[number];","    } else if (number % 10 == 0) {","        return tens[number / 10];","    } else {","        return tens[number / 10] + \"-\" + ones[number % 10];","    }","}","","std::string below_thousand(unsigned long long number)","{","    const std::string hundreds {below_hundred(number / 100)};","    if (number < 100) {","        return below_hundred(number);","    } else if (number % 100 == 0) {","        return hundreds + \" hundred\";","    } else {","        return hundreds + \" hundred \"","            + below_hundred(number % 100);","    }","}","","std::string in_english(unsigned long long number)","{","    if (number > 999'999'999'999) {","        throw std::domain_error {\"the number is too large\"};","    }","    if (number == 0) {","        return \"zero\";","    }","    const std::vector<std::string> powers {","        \"\", \" thousand\", \" million\", \" billion\"};","    std::string result {\"\"};","    std::size_t power {0};","    while (number > 0) {","        const unsigned long long last {number % 1000};","        if (last != 0) {","            std::string words {below_thousand(last)};","            words += powers[power];","            if (!result.empty()) {","                words += \" \" + result;","            }","            result = words;","        }","        number /= 1000;","        ++power;","    }","    return result;","}","","}  // namespace say"],"frame":[0,2,3,4,6,68],"labels":[{"at":8,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":10,"level":2,"text":"Make the words for 0 to 19 and for each ten."},{"at":18,"level":2,"text":"Give back the word for a number below 20, the ten for a multiple of 10, else the ten, a dash and the last digit."},{"at":27,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":29,"level":2,"text":"Give back the words for a number below 100, the hundreds for a multiple of 100, else the hundreds and the rest."},{"at":40,"level":1,"text":"Write a function that repeats a step until a condition holds and gives back the result."},{"at":42,"level":2,"text":"Throw `std::domain_error` for a number above 999 999 999 999."},{"at":45,"level":2,"text":"Give back `zero` for 0."},{"at":48,"level":2,"text":"Make the word for each power of 1000."},{"at":50,"level":2,"text":"Start the result as an empty string."},{"at":51,"level":2,"text":"Start the power at 0."},{"at":52,"level":2,"text":"While the number is above 0, put the words for its last 3 digits, when not 0, at the front of the result, then drop them."},{"at":65,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":26,"to":51},{"line":16,"from":45,"to":52},{"line":18,"from":8,"to":19},{"line":27,"from":27,"to":52},{"line":30,"from":8,"to":20},{"line":40,"from":23,"to":48},{"line":42,"from":8,"to":32},{"line":45,"from":8,"to":19},{"line":49,"from":25,"to":35},{"line":50,"from":24,"to":26},{"line":51,"from":23,"to":24},{"line":52,"from":11,"to":21},{"line":65,"from":11,"to":17}]},"fn":{"slug":"say","commit":"8d139cb0","header":"say.h","name":"say_test.cpp","test":"#include \"say.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nTEST_CASE(\"zero\", \"[5d22a120-ba0c-428c-bd25-8682235d83e8]\") {\n    REQUIRE(\"zero\" == say::in_english(0));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"one\", \"[9b5eed77-dbf6-439d-b920-3f7eb58928f6]\") {\n    REQUIRE(\"one\" == say::in_english(1));\n}\n\nTEST_CASE(\"fourteen\", \"[7c499be1-612e-4096-a5e1-43b2f719406d]\") {\n    REQUIRE(\"fourteen\" == say::in_english(14));\n}\n\nTEST_CASE(\"twenty\", \"[f541dd8e-f070-4329-92b4-b7ce2fcf06b4]\") {\n    REQUIRE(\"twenty\" == say::in_english(20));\n}\n\nTEST_CASE(\"twenty-two\", \"[d78601eb-4a84-4bfa-bf0e-665aeb8abe94]\") {\n    REQUIRE(\"twenty-two\" == say::in_english(22));\n}\n\nTEST_CASE(\"thirty\", \"[f010d4ca-12c9-44e9-803a-27789841adb1]\") {\n    REQUIRE(\"thirty\" == say::in_english(30));\n}\n\nTEST_CASE(\"ninety-nine\", \"[738ce12d-ee5c-4dfb-ad26-534753a98327]\") {\n    REQUIRE(\"ninety-nine\" == say::in_english(99));\n}\n\nTEST_CASE(\"one hundred\", \"[e417d452-129e-4056-bd5b-6eb1df334dce]\") {\n    REQUIRE(\"one hundred\" == say::in_english(100));\n}\n\nTEST_CASE(\"one hundred twenty-three\",\n          \"[d6924f30-80ba-4597-acf6-ea3f16269da8]\") {\n    REQUIRE(\"one hundred twenty-three\" == say::in_english(123));\n}\n\nTEST_CASE(\"two hundred\", \"[2f061132-54bc-4fd4-b5df-0a3b778959b9]\") {\n    REQUIRE(\"two hundred\" == say::in_english(200));\n}\n\nTEST_CASE(\"nine hundred ninety-nine\",\n          \"[feed6627-5387-4d38-9692-87c0dbc55c33]\") {\n    REQUIRE(\"nine hundred ninety-nine\" == say::in_english(999));\n}\n\nTEST_CASE(\"one thousand\", \"[3d83da89-a372-46d3-b10d-de0c792432b3]\") {\n    REQUIRE(\"one thousand\" == say::in_english(1000));\n}\n\nTEST_CASE(\"one thousand two hundred thirty-four\",\n          \"[865af898-1d5b-495f-8ff0-2f06d3c73709]\") {\n    REQUIRE(\"one thousand two hundred thirty-four\" == say::in_english(1234));\n}\n\nTEST_CASE(\"one million\", \"[b6a3f442-266e-47a3-835d-7f8a35f6cf7f]\") {\n    REQUIRE(\"one million\" == say::in_english(1000000));\n}\n\nTEST_CASE(\"one million two thousand three hundred forty-five\",\n          \"[2cea9303-e77e-4212-b8ff-c39f1978fc70]\") {\n    REQUIRE(\"one million two thousand three hundred forty-five\" ==\n            say::in_english(1002345));\n}\n\nTEST_CASE(\"one billion\", \"[3e240eeb-f564-4b80-9421-db123f66a38f]\") {\n    REQUIRE(\"one billion\" == say::in_english(1000000000));\n}\n\nTEST_CASE(\"a big number\", \"[9a43fed1-c875-4710-8286-5065d73b8a9e]\") {\n    REQUIRE(\n        \"nine hundred eighty-seven billion six hundred fifty-four million \"\n        \"three hundred twenty-one thousand one hundred twenty-three\" ==\n        say::in_english(987654321123));\n}\n\nTEST_CASE(\"numbers below zero are out of range\",\n          \"[49a6a17b-084e-423e-994d-a87c0ecc05ef]\") {\n    REQUIRE_THROWS_AS(say::in_english(-1), std::domain_error);\n}\n\nTEST_CASE(\"numbers above 999,999,999,999 are out of range\",\n          \"[4d6492eb-5853-4d16-9d34-b0f61b261fd9]\") {\n    REQUIRE_THROWS_AS(say::in_english(1000000000000), std::domain_error);\n}\n\n#endif\n","setup":[],"calls":[{"call":"say::in_english(0)","expected":"\"zero\""}]}},"73.02":{"id":"73.02","kind":73,"source":"aether","statement":["Write a function `short_scale::say(long long number)` that returns the number as a `std::string` of its groups of 3 digits, counted from the right, each written in digits with no zeros in front and followed by its word.","The words, from the right, are none, `thousand`, `million` and `billion`; a group of 0 is left out, and a single space stands between 2 parts.","1234567 gives `1 million 234 thousand 567`, 2000500 gives `2 million 500`, and 0 gives `0`.","Limits: 0 ≤ number ≤ 999 999 999 999."],"examples":[{"input":"millions","output":""}],"tests":[{"input":"zero","output":""},{"input":"one_digit","output":""},{"input":"three_digits","output":""},{"input":"one_thousand","output":""},{"input":"zeros_inside_dropped","output":""},{"input":"middle_group_of_zero","output":""},{"input":"group_with_zeros_in_front","output":""},{"input":"one_billion","output":""},{"input":"largest","output":""}],"solution":{"lines":["#pragma once","","#include <string>","","namespace short_scale {","","std::string power_word(int power)","{","    if (power == 0) {","        return \"\";","    } else if (power == 1) {","        return \" thousand\";","    } else if (power == 2) {","        return \" million\";","    } else {","        return \" billion\";","    }","}","","std::string group_words(long long group, int power)","{","    if (group == 0) {","        return \"\";","    } else {","        return std::to_string(group) + power_word(power);","    }","}","","std::string say(long long number)","{","    if (number == 0) {","        return \"0\";","    }","    std::string result {\"\"};","    int power {0};","    while (number > 0) {","        std::string words {group_words(number % 1000, power)};","        if (!words.empty() && !result.empty()) {","            words += \" \" + result;","        }","        if (!words.empty()) {","            result = words;","        }","        number /= 1000;","        ++power;","    }","    return result;","}","","}  // namespace short_scale"],"frame":[0,2,4,49],"labels":[{"at":6,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":8,"level":2,"text":"Give back no word for power 0, `thousand` for 1, `million` for 2, else `billion`."},{"at":19,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":21,"level":2,"text":"Give back nothing for a group of 0, else the group and the word for its power."},{"at":28,"level":1,"text":"Write a function that repeats a step until a condition holds and gives back the result."},{"at":30,"level":2,"text":"Give back `0` for 0."},{"at":33,"level":2,"text":"Start the result as an empty string."},{"at":34,"level":2,"text":"Start the power at 0."},{"at":35,"level":2,"text":"While the number is above 0, put the words for its last 3 digits, when not 0, at the front of the result, then drop them."},{"at":46,"level":2,"text":"Give back the result."}],"blanks":[{"line":6,"from":23,"to":32},{"line":8,"from":8,"to":18},{"line":19,"from":24,"to":39},{"line":21,"from":8,"to":18},{"line":28,"from":16,"to":32},{"line":30,"from":8,"to":19},{"line":33,"from":24,"to":26},{"line":34,"from":15,"to":16},{"line":35,"from":11,"to":21},{"line":46,"from":11,"to":17}]},"fn":{"slug":"short_scale","commit":"","header":"short_scale.h","name":"short_scale_test.cpp","test":"#include \"short_scale.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"millions\") { REQUIRE(short_scale::say(1234567) == \"1 million 234 thousand 567\"); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"zero\") { REQUIRE(short_scale::say(0) == \"0\"); }\nTEST_CASE(\"one_digit\") { REQUIRE(short_scale::say(7) == \"7\"); }\nTEST_CASE(\"three_digits\") { REQUIRE(short_scale::say(999) == \"999\"); }\nTEST_CASE(\"one_thousand\") { REQUIRE(short_scale::say(1000) == \"1 thousand\"); }\nTEST_CASE(\"zeros_inside_dropped\")\n{\n    REQUIRE(short_scale::say(1000001) == \"1 million 1\");\n}\nTEST_CASE(\"middle_group_of_zero\")\n{\n    REQUIRE(short_scale::say(2000500) == \"2 million 500\");\n}\nTEST_CASE(\"group_with_zeros_in_front\")\n{\n    REQUIRE(short_scale::say(5007) == \"5 thousand 7\");\n}\nTEST_CASE(\"one_billion\") { REQUIRE(short_scale::say(1000000000) == \"1 billion\"); }\nTEST_CASE(\"largest\")\n{\n    REQUIRE(short_scale::say(999999999999)\n            == \"999 billion 999 million 999 thousand 999\");\n}\n#endif\n","setup":[],"calls":[{"call":"short_scale::say(1234567)","expected":"\"1 million 234 thousand 567\""}]}}}}
